#!/usr/bin/env node
// Generates every derived contract artifact from contracts/openapi.yaml + contracts/fixtures.
//   node contracts/scripts/generate.mjs          write files
//   node contracts/scripts/generate.mjs --check  exit 1 if any generated file is stale
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { contractsDir, fixtureSchema, loadSpec, operations, refName, typeName } from "./spec.mjs";
import { generateTs } from "./gen-ts.mjs";
import { generateDart } from "./gen-dart.mjs";

function widgetSnapshotSchema(spec) {
  const schemas = spec.components.schemas;
  const defs = {};
  const strip = (node) => {
    if (Array.isArray(node)) return node.map(strip);
    if (!node || typeof node !== "object") return node;
    const out = {};
    for (const [k, v] of Object.entries(node)) {
      if (k.startsWith("x-")) continue;
      if (k === "$ref") { const name = refName(v); visit(name); out.$ref = `#/$defs/${name}`; continue; }
      out[k] = strip(v);
    }
    return out;
  };
  const visit = (name) => { if (defs[name]) return; defs[name] = {}; defs[name] = strip(schemas[name]); };
  const root = strip(schemas.WidgetSnapshot);
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://hontogame.com/contracts/widget-snapshot.v1.json",
    title: "Honto widget snapshot v1 (snapshot.v1.json)",
    $comment: "GENERATED from contracts/openapi.yaml#/components/schemas/WidgetSnapshot. Do not edit by hand.",
    ...root,
    $defs: Object.fromEntries(Object.entries(defs).sort(([a], [b]) => a.localeCompare(b))),
  };
}

function dartFixtures(spec) {
  const ops = operations(spec);
  const dir = join(contractsDir, "fixtures");
  const files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
  const lines = [
    "// GENERATED by contracts/scripts/generate.mjs from contracts/fixtures/*.json. Do not edit by hand.",
    "// ignore_for_file: type=lint",
    "",
    "/// Fixture bodies keyed by file name without `.json` (e.g. `getToday.200`, `joinCouple.409.already_paired`).",
    "const Map<String, String> hontoFixtures = <String, String>{",
  ];
  for (const f of files) {
    const json = JSON.stringify(JSON.parse(readFileSync(join(dir, f), "utf8")));
    if (json.includes("'''")) throw new Error(`${f} contains ''' which cannot be embedded`);
    lines.push(`  '${f.replace(/\.json$/, "")}': r'''${json}''',`);
  }
  lines.push("};", "", "/// Schema (Dart type name) each fixture conforms to.", "const Map<String, String> hontoFixtureTypes = <String, String>{");
  for (const f of files) { const key = f.replace(/\.json$/, ""); lines.push(`  '${key}': '${typeName(fixtureSchema(spec, ops, key))}',`); }
  lines.push("};", "");
  return lines.join("\n");
}

export function buildAll() {
  const spec = loadSpec();
  const dart = generateDart(spec);
  return {
    "honto-api.ts": generateTs(spec),
    "dart/lib/src/models.g.dart": dart.models,
    "dart/lib/src/api.g.dart": dart.api,
    "dart/lib/src/fixtures.g.dart": dartFixtures(spec),
    "widget-snapshot.v1.json": JSON.stringify(widgetSnapshotSchema(spec), null, 2) + "\n",
  };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const check = process.argv.includes("--check");
  const stale = [];
  for (const [rel, content] of Object.entries(buildAll())) {
    const path = join(contractsDir, rel);
    const current = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (current === content) continue;
    if (check) stale.push(rel); else { writeFileSync(path, content); console.log(`wrote contracts/${rel}`); }
  }
  if (check && stale.length) { console.error(`Stale generated files (run npm run contracts:generate):\n  ${stale.join("\n  ")}`); process.exit(1); }
  if (check) console.log("contracts: generated files are up to date");
}
